import {useConfig} from "./Config";

// Extend the Window interface to include __homepageconfigwebresourceurl__
declare global {
  interface Window {
    __homepageconfigwebresourceurl__: string;
  }
}

const configUrl = window.__homepageconfigwebresourceurl__ as string ?? '';

const Home = () => {
    // Use the custom hook - replace 'your_config_webresource_name' with your actual WebResource name
    const { config, loading, error, reloadConfig } = useConfig(configUrl);

    if (loading) {
      return (
        <div style={{ padding: '20px', textAlign: 'center' }}>
          <div>Loading configuration...</div>
        </div>
      );
    }
  
    if (error) {
      return (
        <div style={{ padding: '20px', color: 'red' }}>
          <h3>Error loading configuration:</h3>
          <p>{error}</p>
          <button onClick={reloadConfig} style={{ marginTop: '10px' }}>
            Retry
          </button>
        </div>
      );
    }
  
    if (!config) {
      return (
        <div style={{ padding: '20px' }}>
          <div>No configuration found</div>
          <button onClick={reloadConfig} style={{ marginTop: '10px' }}>
            Retry
          </button>
        </div>
      );
    }
  
    return (
      <div style={{ padding: '20px' }}>
        <h1>{config.title}</h1>
        <p>{config.description}</p>
        
        {/* Display all configuration properties */}
        <div style={{ marginTop: '20px' }}>
          <h2>Configuration Details:</h2>
          <pre style={{ 
            backgroundColor: '#f5f5f5', 
            padding: '15px', 
            borderRadius: '5px',
            overflow: 'auto'
          }}>
            {JSON.stringify(config, null, 2)}
          </pre>
          
          <button 
            onClick={reloadConfig} 
            style={{ 
              marginTop: '10px',
              padding: '8px 16px',
              backgroundColor: '#007cba',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Reload Configuration
          </button>
        </div>
      </div>
    );
  };
  
  export default Home;